import { DesktopSignatureParameters } from "autogram-sdk";
import {
  ObjectStrategy,
} from "./filetype-strategy/base-strategy";
import {
  XadesBpPngStrategy,
  XadesBpTxtStrategy,
  XadesBpXmlStrategy,
  XadesPdfStrategy,
  XadesXmlStrategy,
  XadesBp2XmlStrategy,
} from "./filetype-strategy";
import { InputObject } from "./types";

export const SigningStatus = {
  new: "new",
  started: "started",
  signed: "signed",
} as const;
export class SignRequest {
  object: InputObject;
  private objectInfo: ObjectStrategy;

  public signatureId: string;
  public digestAlgUri: string;
  public signaturePolicyIdentifier: string;
  public signingStatus: ValueOf<typeof SigningStatus> = SigningStatus.new;

  // objects = [];
  // get object(): InputObject {
  //   return this.objects[0];
  // }

  public addObject(obj: InputObject): void {
    if (this.object && this.signingStatus !== SigningStatus.signed) {
      console.error("ERROR: overwriting unsigned object");
    }
    this.object = obj;
    this.objectInfo = this.getObjectInfo();
  }

  public signatureParameters(
    params: Partial<DesktopSignatureParameters>
  ): DesktopSignatureParameters {
    // const containerXmlns = getProperty(
    //   params,
    //   "containerXmlns",
    //   "http://data.gov.sk/def/container/xmldatacontainer+xml/1.1"
    // );

    const containerXmlns =
      this.object.type === "Xades2Xml" ||
      this.object.type === "XadesXml" ||
      this.object.type === "XadesBp2Xml" ||
      this.object.type === "XadesBpXml"
        ? "http://data.gov.sk/def/container/xmldatacontainer+xml/1.1"
        : null;

    return {
      identifier: this.objectInfo.identifier,
      level: getProperty(params, "form", "XAdES_BASELINE_B"),
      container: getProperty(params, "container", "ASICE"),
      containerXmlns: containerXmlns ?? undefined,
      packaging: getProperty(params, "packaging", "ENVELOPING"),
      digestAlgorithm: getProperty(params, "digestAlgorithm", "SHA256"),
      en319132: getProperty(params, "en319132", false),
      infoCanonicalization: getProperty(
        params,
        "infoCanonicalization",
        "INCLUSIVE"
      ),
      propertiesCanonicalization: getProperty(
        params,
        "propertiesCanonicalization",
        "INCLUSIVE"
      ),
      keyInfoCanonicalization: getProperty(
        params,
        "keyInfoCanonicalization",
        "INCLUSIVE"
      ),
      transformation: this.objectInfo.objTransformation,
      schema: this.objectInfo.objSchema,
      checkPDFACompliance: true,
      schemaIdentifier: getNullIfEmpty(this.objectInfo.schemaIdentifier),
      transformationIdentifier: getNullIfEmpty(
        this.objectInfo.transformationIdentifier
      ),
      transformationMediaDestinationTypeDescription: getNullIfEmpty(
        this.objectInfo.transformationMediaDestinationTypeDescription
      ),
      transformationLanguage: getNullIfEmpty(
        this.objectInfo.transformationLanguage
      ),
      transformationTargetEnvironment: getNullIfEmpty(
        this.objectInfo.transformationTargetEnvironment
      ),
      /* including (schema) references is inverse of embedding schemas */
      embedUsedSchemas: !this.objectInfo.includeRefs,
    };
  }

  private getObjectInfo(): ObjectStrategy {
    const obj = this.object;
    switch (obj.type) {
      case "XadesBpXml":
        return new XadesBpXmlStrategy(obj);

      case "XadesXml":
      case "Xades2Xml":
        return new XadesXmlStrategy(obj);

      case "XadesBp2Xml":
        return new XadesBp2XmlStrategy(obj);

      case "XadesPdf":
      case "XadesBpPdf":
        return new XadesPdfStrategy(obj);

      case "XadesBpPng":
      case "XadesPng":
        return new XadesBpPngStrategy(obj);

      case "XadesBpTxt":
        return new XadesBpTxtStrategy(obj);

      default:
        throw new Error("failed");
    }
  }

  get document() {
    return this.objectInfo.document;
  }

  get payloadMimeType() {
    return this.objectInfo.payloadMimeType;
  }
}

/**
 * Gets property from object or returns defaultValue
 * @param obj
 * @propertyName propertyName
 * @param defaultValue
 * @returns
 */
function getProperty<T>(obj: object, propertyName: string, defaultValue: T) {
  return Object.prototype.hasOwnProperty.call(obj, propertyName)
    ? obj[propertyName]
    : defaultValue;
}

function getNullIfEmpty<A extends { length: number }>(
  s: A | undefined
): A | undefined {
  return s != null && s != null && s.length > 0 ? s : undefined;
}

// function assertUnreachable(x: never): never {
//   throw new Error("Didn't expect to get here");
// }

type ValueOf<T> = T[keyof T];
